    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static void atomic(ServerMatch m,Runnable r){var a=m.privateView(A);var b=m.privateView(B);var v=m.clientView(A);var rng=m.randomTranscript();reject(r);check(a.equals(m.privateView(A))&&b.equals(m.privateView(B))&&v.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Rejected action changed zones, field or RNG");}
    static CardDefinition synthetic(String id,CardCategory category,TrainerCategory trainer,boolean basic){return new CardDefinition(id,id,category,trainer,"J",Set.of("international"),basic,category==CardCategory.ENERGY,60,Map.of(),EffectSupport.SUPPORTED,null);}
    static ServerMatch game(){return game(CARD,false,"NORMAL");}
    static ServerMatch game(String card,boolean copied,String mode){
        var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();for(String id:List.of(BASE,CARD,ALT,PHANTUMP,TREV)){defs.add(DB.find(id).orElseThrow());profiles.put(id,DATA.pokemon(id).orElseThrow());}
        for(String id:List.of("plain","evolved"))defs.add(synthetic(id,CardCategory.POKEMON,TrainerCategory.NONE,id.equals("plain")));
        for(String id:List.of("psychic","wrong"))defs.add(synthetic(id,CardCategory.ENERGY,TrainerCategory.NONE,false));
        for(String id:List.of("boost","reduce","hp","fossil"))defs.add(synthetic(id,CardCategory.TRAINER,id.equals("fossil")?TrainerCategory.ITEM:TrainerCategory.TOOL,false));
        var attacks=List.of(GeneratedRuleBatch8Test.hit(10,false),CopyAttackTest.copier());
        for(String id:List.of("plain","evolved"))profiles.put(id,new PokemonProfile(2000,1,id.equals("evolved")?"plain":null,mode.equals("WEAK")?EnergyType.PSYCHIC:null,mode.equals("WEAK")?2:0,mode.equals("RESIST")?EnergyType.PSYCHIC:null,mode.equals("RESIST")?30:0,1,attacks,List.of(),EnergyType.COLORLESS));
        var trainers=Map.of("boost",DynamicPassiveModifierTest.trainer("TOOL","{\"type\":\"attack_damage_modifier\",\"direction\":\"DEALT\",\"amount\":20}"),"reduce",DynamicPassiveModifierTest.trainer("TOOL","{\"type\":\"attack_damage_modifier\",\"direction\":\"RECEIVED\",\"amount\":-30}"),"hp",DynamicPassiveModifierTest.trainer("TOOL","{\"type\":\"hit_points_modifier\",\"amount\":100}"),"fossil",FossilFormTest.fossil());
        var combat=new CombatCatalog(profiles,Map.of("psychic",EnergyType.PSYCHIC,"wrong",EnergyType.FIRE),trainers);
        String[] pool={BASE,BASE,BASE,card,card,card,PHANTUMP,PHANTUMP,PHANTUMP,TREV,TREV,TREV,"plain","plain","plain","plain","plain","plain","plain","plain","psychic","psychic","psychic","wrong","wrong","evolved","boost","reduce","hp","fossil"};
        UUID owner=copied?B:A;String af=copied?"plain":BASE,bf=copied?BASE:"plain";
        for(int seed=0;seed<6000;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pool[i%pool.length]));decks.add(cards);}
            var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(A).hand().stream().filter(c->c.definitionId().equals(af)).count()<(af.equals("plain")?2:1)||m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals("plain"))||m.privateView(B).hand().stream().filter(c->c.definitionId().equals(bf)).count()<(bf.equals("plain")?2:1)||m.privateView(B).hand().stream().noneMatch(c->c.definitionId().equals("plain")))continue;
            m.chooseOpeningActive(A,hand(m,A,af).instanceId());m.placeOpeningBench(A,hand(m,A,"plain").instanceId());m.chooseOpeningActive(B,hand(m,B,bf).instanceId());m.placeOpeningBench(B,hand(m,B,"plain").instanceId());m.startAfterOpening(A);m.startAfterOpening(B);OpeningTestSupport.complete(m,A,B,0);m.drawCardsByEffect(A,A,30);m.drawCardsByEffect(A,B,30);m.endTurn(A);m.endTurn(B);
            if(List.of(A,B).stream().anyMatch(p->Arrays.stream(pool).distinct().anyMatch(id->m.privateView(p).hand().stream().noneMatch(c->c.definitionId().equals(id))))||m.privateView(A).hand().stream().filter(c->c.definitionId().equals("plain")).count()<4||List.of(A,B).stream().anyMatch(p->List.of("psychic",PHANTUMP,TREV).stream().anyMatch(id->m.privateView(p).hand().stream().filter(c->c.definitionId().equals(id)).count()<2)))continue;
            if(m.privateView(owner).hand().stream().filter(c->c.definitionId().equals(card)).count()<2)continue;
            if(copied)m.endTurn(A);check(m.canEvolve(owner,active(m,owner),card),"Actual named Pumpkaboo evolution unavailable");m.evolve(owner,active(m,owner),hand(m,owner,card).instanceId());if(copied)m.endTurn(B);return m;
        }throw new AssertionError("No actual Gourgeist fixture "+card+"/"+copied+"/"+mode);
    }
    static void attach(ServerMatch m,UUID owner,String id){var c=hand(m,owner,id);m.attachEnergyByEffect(m.currentPlayer(),owner,EffectSourceZone.HAND,c.instanceId(),owner,active(m,owner));}
    static UUID enter(ServerMatch m,UUID owner,String id){var c=hand(m,owner,id);m.playBasicPokemonToBench(owner,c.instanceId());return PokemonIdentityTestSupport.logical(m,owner,c.instanceId());}
    static void ready(ServerMatch m){check(m.currentPlayer().equals(B),"Attack did not end own turn");m.endTurn(B);}
    static void damage(ServerMatch m,int expected){int before=m.activePokemonView(B).damage();var rng=m.randomTranscript();m.attack(A,RONDO);check(m.lastAttack().finalDamage()==expected&&m.activePokemonView(B).damage()==before+expected&&m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice()&&m.randomTranscript().equals(rng),"Actual Rondo expected "+expected);}
    static void counter(ServerMatch m,UUID owner,UUID target,int n){m.placeDamageCountersByEffect(m.currentPlayer(),owner,target,n);}
    static void shield(ServerMatch m,String scope){var e=EffectRegistry.standard().parse(JsonParser.parseString(EffectOriginProtectionTest.shield("ATTACK",scope,"OPPONENT_ACTIVE","LEAVES_PLAY")).getAsJsonObject());m.executeEffectProgramByRule(A,active(m,A),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e)))),EffectTrigger.ON_CARD_PLAYED);}
    static void exactHand(ServerMatch m,UUID owner,int n){var cards=m.privateView(owner).hand();check(cards.size()>=n,"Short hand fixture");var discard=cards.subList(n,cards.size()).stream().map(CardInstance::instanceId).toList();if(!discard.isEmpty())m.discardHandCardsByEffect(m.currentPlayer(),owner,discard);}
    static void privacy(ServerMatch m){var session=MatchSession.multiplayer(m,A,B);session.addSpectator(WATCH);var rng=m.randomTranscript();for(UUID viewer:List.of(A,B,WATCH)){String json=new Gson().toJson(session.view(viewer,viewer.equals(WATCH)?null:viewer));for(UUID owner:List.of(A,B)){if(!viewer.equals(owner))for(var c:m.privateView(owner).hand())check(!json.contains(c.instanceId().toString()),"Ghostly Touch exposed opposing physical hand identity");for(var c:m.privateView(owner).deck())check(!json.contains(c.instanceId().toString()),"Ghostly Touch exposed hidden deck identity");}}check(m.randomTranscript().equals(rng),"View refresh consumed random choice");}
    static void phantom(ServerMatch m,UUID source){m.useAbility(A,source,"spiteful-evolution");var p=m.effectCardPrompt(A);var chosen=p.candidates().stream().filter(c->c.definitionId().equals(TREV)).findFirst().orElseThrow();m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId()));check(!m.hasPendingEffectChoice(),"Actual88 evolution did not complete");}
    public static void main(String[]args){printed();countsAndScope();liveHostChanges();actualPhantumpSynergy();mixedFieldForms();liveBenchMembership();modifiersAndProtection();copiedActor();ghostlyTouch();twoPrizes();System.out.println("GeneratedRuleBatch89Test passed: both actual Gourgeist ex prints, normal Pumpkaboo evolution, live damaged-own-Bench host count and actual Phantump/Trevenant synergy, modifiers and copied actor, unchanged PP140 server-random private hand discard and two prizes");}
    static void printed(){var base=DATA.pokemon(BASE).orElseThrow();check(DB.find(BASE).orElseThrow().effectSupport()==EffectSupport.SUPPORTED&&DB.find(BASE).orElseThrow().basicPokemon()&&base.hitPoints()==60&&base.pokemonType()==EnergyType.PSYCHIC&&base.retreatCost()==2&&base.prizeCards()==1&&base.attacks().size()==1&&base.attacks().getFirst().id().equals("stampede")&&base.attacks().getFirst().baseDamage()==20&&base.attacks().getFirst().energyCost().equals(Map.of(EnergyType.PSYCHIC,1)),"Actual Pumpkaboo040 profile");for(String id:PRINTS){var c=DB.find(id).orElseThrow();var p=DATA.pokemon(id).orElseThrow();check(c.effectSupport()==EffectSupport.SUPPORTED&&!c.basicPokemon()&&c.pokemonFamilies().containsAll(Set.of(PokemonFamily.EX,PokemonFamily.RULE_BOX))&&p.hitPoints()==270&&p.pokemonType()==EnergyType.PSYCHIC&&p.weaknessType()==EnergyType.DARKNESS&&p.weaknessMultiplier()==2&&p.resistanceType()==EnergyType.FIGHTING&&p.resistanceAmount()==30&&p.retreatCost()==2&&p.prizeCards()==2&&p.evolvesFromName().equals("Pumpkaboo")&&p.abilities().isEmpty(),"Actual Gourgeist metadata "+id);check(p.attacks().size()==2&&p.attacks().getFirst().id().equals(RONDO)&&p.attacks().getFirst().baseDamage()==30&&p.attacks().getFirst().energyCost().equals(Map.of(EnergyType.PSYCHIC,1))&&p.attacks().getLast().id().equals(GHOST)&&p.attacks().getLast().baseDamage()==140&&p.attacks().getLast().energyCost().equals(Map.of(EnergyType.PSYCHIC,2)),"Actual printed attack costs/base damage "+id);for(var attack:p.attacks())AttackProgramRules.validate(attack);var m=game(id,false,"NORMAL");check(m.activePokemonView(A).evolutionCardIds().equals(List.of(BASE,id)),"Real normal named evolution including alternate print");atomic(m,()->m.attack(A,RONDO));attach(m,A,"wrong");atomic(m,()->m.attack(A,RONDO));attach(m,A,"psychic");atomic(m,()->m.attack(A,GHOST));damage(m,30);}}
    static void countsAndScope(){for(String id:PRINTS)for(int count:List.of(0,1,2,5)){var m=game(id,false,"NORMAL");attach(m,A,"psychic");while(m.benchPokemonView(A).size()<5)enter(m,A,"plain");for(int i=0;i<count;i++)counter(m,A,m.benchPokemonView(A).get(i).pokemonId(),i+1);counter(m,A,active(m,A),2);counter(m,B,active(m,B),7);counter(m,B,m.benchPokemonView(B).getFirst().pokemonId(),8);var own=m.benchPokemonView(A);var opposing=m.benchPokemonView(B);damage(m,30+count*50);check(m.benchPokemonView(A).equals(own)&&m.benchPokemonView(B).equals(opposing),"Rondo moved counters or damaged Bench instead of normal active damage");}}
    static void liveHostChanges(){var m=game();attach(m,A,"psychic");UUID target=m.benchPokemonView(A).getFirst().pokemonId();counter(m,A,target,3);damage(m,80);ready(m);m.healDamageByEffect(A,A,target,10);damage(m,80);ready(m);m.healDamageByEffect(A,A,target,20);damage(m,30);ready(m);counter(m,A,target,2);m.evolve(A,target,hand(m,A,"evolved").instanceId());damage(m,80);ready(m);m.devolvePokemonToHandByEffect(A,A,target);damage(m,80);ready(m);UUID physical=PokemonIdentityTestSupport.physical(m,A,target);m.movePokemonByEffect(A,A,target,LeavePlayDestination.HAND);damage(m,30);ready(m);m.playBasicPokemonToBench(A,physical);UUID newEntry=PokemonIdentityTestSupport.logical(m,A,physical);check(!newEntry.equals(target),"New logical entry fixture");damage(m,30);ready(m);counter(m,A,newEntry,1);damage(m,80);}
    static void actualPhantumpSynergy(){for(String id:PRINTS){var m=game(id,false,"NORMAL");attach(m,A,"psychic");UUID first=enter(m,A,PHANTUMP),second=enter(m,A,PHANTUMP);check(!m.canEvolve(A,first,TREV),"Fresh actual Phantump unexpectedly allows ordinary evolution");phantom(m,first);phantom(m,second);check(m.benchPokemonView(A).stream().filter(p->p.topCardId().equals(TREV)&&p.damage()==20&&p.evolutionCardIds().equals(List.of(PHANTUMP,TREV))).count()==2,"Actual88 two host evolution/counter synergy");damage(m,130);ready(m);m.healDamageByEffect(A,A,first,10);damage(m,130);ready(m);m.healDamageByEffect(A,A,first,10);damage(m,80);}}
    static void mixedFieldForms(){var m=game();attach(m,A,"psychic");UUID ordinary=m.benchPokemonView(A).getFirst().pokemonId();m.playTrainer(A,hand(m,A,"hp").instanceId(),ordinary);check(m.benchPokemonView(A).getFirst().hitPoints()==2100&&m.benchPokemonView(A).getFirst().damage()==0,"HP modifier fixture");var fossil=hand(m,A,"fossil");m.playTrainer(A,fossil.instanceId(),null);UUID fossilHost=PokemonIdentityTestSupport.logical(m,A,fossil.instanceId());counter(m,A,fossilHost,1);damage(m,80);ready(m);UUID pumpkin=enter(m,A,BASE);m.endTurn(A);m.endTurn(B);m.evolve(A,pumpkin,hand(m,A,CARD).instanceId());counter(m,A,pumpkin,4);m.evolve(A,ordinary,hand(m,A,"evolved").instanceId());counter(m,A,ordinary,2);damage(m,180);check(m.benchPokemonView(A).stream().filter(p->p.topCardId().equals(CARD)).count()==1,"Actual rule-box host fixture missing");}
    static void liveBenchMembership(){var m=game();attach(m,A,"psychic");UUID first=active(m,A),second=enter(m,A,BASE);m.endTurn(A);m.endTurn(B);m.evolve(A,second,hand(m,A,CARD).instanceId());var energy=hand(m,A,"psychic");m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,energy.instanceId(),A,second);counter(m,A,first,1);damage(m,30);ready(m);m.switchActiveByEffect(A,A,second);damage(m,80);ready(m);m.switchActiveByEffect(A,A,first);damage(m,30);}
    static void modifiersAndProtection(){for(String mode:List.of("WEAK","RESIST","BOOST","REDUCE","DAMAGE_GUARD","EFFECTS_GUARD")){var m=game(CARD,false,mode);attach(m,A,"psychic");counter(m,A,m.benchPokemonView(A).getFirst().pokemonId(),4);if(mode.equals("BOOST"))m.playTrainer(A,hand(m,A,"boost").instanceId(),active(m,A));if(mode.equals("REDUCE")){m.endTurn(A);m.playTrainer(B,hand(m,B,"reduce").instanceId(),active(m,B));m.endTurn(B);}if(mode.equals("DAMAGE_GUARD"))shield(m,"DAMAGE_ONLY");if(mode.equals("EFFECTS_GUARD"))shield(m,"EFFECTS_ONLY");damage(m,switch(mode){case "WEAK"->160;case "RESIST","REDUCE"->50;case "BOOST"->100;case "DAMAGE_GUARD"->0;default->80;});}}
    static void copiedActor(){for(String id:PRINTS)for(int own:List.of(0,1,2)){var m=game(id,true,"NORMAL");attach(m,A,"wrong");if(own==2)enter(m,A,"plain");for(int i=0;i<own;i++)counter(m,A,m.benchPokemonView(A).get(i).pokemonId(),i+2);counter(m,A,active(m,A),2);counter(m,B,m.benchPokemonView(B).getFirst().pokemonId(),5);var option=m.copyAttackOptions(A,"copy").stream().filter(o->o.attackId().equals(RONDO)).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",option.pokemonId(),option.entrySequence(),option.attackId(),List.of(),List.of());check(m.lastAttack().finalDamage()==30+50*own&&m.activePokemonView(B).damage()==30+50*own,"Copied actual Rondo used donor field or wrong host count");}}
    static void ghostlyTouch(){for(String id:PRINTS)for(int handCount:List.of(0,1,6)){var m=game(id,false,"NORMAL");attach(m,A,"psychic");attach(m,A,"psychic");exactHand(m,B,handCount);privacy(m);var before=m.privateView(B);int random=m.randomTranscript().size();int old=m.activePokemonView(B).damage();m.attack(A,GHOST);var discarded=m.privateView(B).discard().subList(before.discard().size(),m.privateView(B).discard().size());check(m.lastAttack().finalDamage()==140&&m.activePokemonView(B).damage()==old+140&&discarded.size()==(handCount==0?0:1)&&discarded.stream().allMatch(before.hand()::contains)&&m.privateView(B).hand().size()==handCount-(handCount==0?0:1)+1&&m.privateView(B).deck().size()==before.deck().size()-1,"Actual Ghostly Touch140 then random discard and ordinary opposing turn draw "+id+"/"+handCount);check(m.randomTranscript().size()==random+(handCount==0?0:1)&&m.randomTranscript().subList(random,m.randomTranscript().size()).stream().allMatch(e->e.operation().startsWith("effect-random-hand-discard:"))&&!m.hasPendingEffectChoice()&&m.effectCardReveal()==null,"Ghostly Touch offered hidden card choice/reveal, or wrong server RNG");privacy(m);}
        // A Pokemon's attack protection does not protect its controller's hand (general rule, no Gourgeist-specific FAQ claimed).
        var guard=game();attach(guard,A,"psychic");attach(guard,A,"psychic");exactHand(guard,B,1);var card=guard.privateView(B).hand().getFirst();shield(guard,"DAMAGE_AND_EFFECTS");guard.attack(A,GHOST);check(guard.lastAttack().finalDamage()==0&&guard.activePokemonView(B).damage()==0&&guard.privateView(B).discard().contains(card),"Pokemon damage/effect guard incorrectly protected controller hand");
    }
    static void twoPrizes(){var m=game(ALT,false,"NORMAL");counter(m,A,active(m,A),27);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.pendingChoicePlayer().equals(B),"Actual Gourgeist ex knockout did not award opponent prizes");int before=m.privateView(B).prizes().size();m.takePrizeAt(B,0);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.pendingChoicePlayer().equals(B),"Actual Gourgeist ex only awarded1 prize");m.takePrizeAt(B,0);check(m.privateView(B).prizes().size()==before-2,"Actual Gourgeist ex prize count");}
